const input = $input.first()?.json ?? {};
const body = input.body && typeof input.body === 'object' ? input.body : input;
const projectName = String(body.project_name ?? body.project ?? body.keyword ?? '').trim();
const rawLimit = Number(body.limit ?? 10);
const limit = Number.isFinite(rawLimit)
  ? Math.min(50, Math.max(1, Math.floor(rawLimit)))
  : 10;

return [{
  json: {
    project_name: projectName,
    limit
  }
}];

const input = $('标准化查询参数').first().json;
const query = String(input.project_name || '').trim().toLocaleLowerCase();
const limit = Number(input.limit) || 10;

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && Object.keys(row).length > 0);

const availableTypes = [...new Set(
  rows.map(row => String(row.memory_type ?? '').trim()).filter(Boolean)
)];

const isProjectRecord = row => {
  const label = [
    row.memory_type,
    row.memory_key,
    row.tags
  ].map(value => String(value ?? '')).join(' ').toLocaleLowerCase();

  return /(project|项目|progress|进度)/i.test(label);
};

const projectRows = rows.filter(isProjectRecord);
const matches = projectRows.filter(row => {
  if (!query) return true;
  const searchable = [
    row.memory_key,
    row.content,
    row.evidence,
    row.tags
  ].map(value => String(value ?? '')).join('\n').toLocaleLowerCase();

  return searchable.includes(query);
});

const items = matches.slice(0, limit).map(row => ({
  memory_key: row.memory_key ?? null,
  memory_type: row.memory_type ?? null,
  content: row.content ?? '',
  evidence: row.evidence ?? '',
  importance: row.importance ?? null,
  tags: row.tags ?? '',
  updatedAt: row.updatedAt ?? null
}));

return [{
  json: {
    success: true,
    project_name: input.project_name || null,
    source: 'n8n Data Table / agent记忆',
    scanned_active_rows: rows.length,
    project_record_count: projectRows.length,
    matched_count: matches.length,
    returned_count: items.length,
    available_memory_types: availableTypes,
    message: matches.length
      ? '已找到项目进度记忆。'
      : projectRows.length
        ? '存在项目类记忆，但没有匹配当前项目名称。'
        : '当前活动记忆表中尚无可识别的项目进度记录。',
    items
  }
}];
